insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('afe9db16-1b83-4292-ba6f-e10ecbe6ac93', 'fr', 'Qu’est-ce que le statut social quand il est question d’attirance ?', '["La réussite financière ou la célébrité", "Le physique seul", "Le nombre d’amis avec qui tu arrives", "La valeur qu’on te prête d’après la façon dont les autres réagissent à toi"]'::jsonb, 'Le statut, c’est la façon dont la salle réagit à toi, ce qui montre que tu es apprécié socialement.')
