insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('53171673-bc87-47f9-a580-371caf722388', 'fr', 'Tu réussis l’entrée en matière et tu discutes facilement, mais ça reste amical. Quel est ton point de blocage ?', '["L’entrée en matière", "La fluidité de la conversation", "Introduire de la tension séductrice ou du jeu", "Concrétiser"]'::jsonb, 'Les résultats changent quand ta pratique se concentre sur le maillon le plus faible de l’échange.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('4195d2ca-e36c-4bd9-bb7e-e178e5d589ca', 'fr', 'Tu lances bien les conversations, mais elles deviennent vite gênantes. Quel est ton point de blocage ?', '["Garder une conversation fluide et la garder impliquée", "Placer tes phrases d’accroche", "Concrétiser et obtenir des numéros", "Aller plus loin physiquement"]'::jsonb, 'Les résultats changent quand ta pratique se concentre sur le maillon le plus faible de l’échange.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('b31c3930-629e-4aab-974a-035d198918d4', 'fr', 'Comment repérer précisément tes points faibles ?', '["Partir du principe que c’est un problème d’assurance en général", "Observer les moments d’échec qui reviennent d’un échange à l’autre", "Repérer à quel moment les choses se défont à chaque fois"]'::jsonb, 'Les points de blocage apparaissent dans des moments précis où ça coince de façon répétée.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('e977c9fd-3fd5-421d-b9c4-259a05b8af45', 'fr', 'Quelles stratégies peuvent t’aider à sortir d’un plateau de progression ?', '["Augmenter volontairement la difficulté", "Changer d’environnement", "Faire une longue pause pour retrouver ta motivation", "Te concentrer sur une micro-compétence précise"]'::jsonb, 'De nouveaux défis obligent à s’adapter et à progresser. Les longues pauses renforcent l’évitement.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('07805ac1-99db-4876-9227-20fb20fbcd1f', 'fr', 'Qu’est-ce qui peut t’aider à paraître mystérieux ?', '["Raconter des histoires sans trop expliquer les détails", "Te dévoiler progressivement au fil de la conversation", "Laisser deviner ta profondeur sans étaler tout ton CV", "Toutes les réponses ci-dessus"]'::jsonb, 'Le mystère garde l’attention en éveil en laissant de la place à la curiosité et à la découverte.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('09518935-f277-43f0-8803-f6f2caa97eee', 'fr', 'Qu’est-ce que l’« esprit d’expérimentation » ?', '["Tester différentes approches pour trouver ce qui marche le mieux", "Voir chaque résultat comme une collecte de données", "Passer de « Est-ce que j’ai réussi ou échoué ? » à « Qu’est-ce que j’ai appris ? »", "Toutes les réponses ci-dessus"]'::jsonb, 'Tant que tu en tires une leçon, la rencontre est une réussite.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('0b4d034c-f347-48a4-bf5e-2826500c82c6', 'fr', 'Tu testes une nouvelle phrase d’accroche, et elle lance une super conversation. Que dois-tu faire ensuite ?', '["Partir du principe qu’elle marchera toujours et ne jamais la changer", "Noter ce qui a marché et tester des variantes pour l’affiner", "Y voir la preuve que tu es désormais parfait", "Arrêter d’expérimenter puisque ça a marché"]'::jsonb, 'La réussite aussi, ce sont des données : sers-t’en pour continuer à apprendre et à ajuster.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('142d920d-753e-4fc3-9a34-043fbf2cb37d', 'fr', 'Quels signaux de statut faible, dans un environnement social, nuisent à l’attirance ?', '["Rester seul près du mur ou dans les coins de la salle", "T’imposer maladroitement dans les conversations", "Ne pas apporter grand-chose à la conversation ou ne parler à personne", "Toutes les réponses ci-dessus"]'::jsonb, 'Les signaux de statut faible viennent du retrait, d’une entrée maladroite ou d’un manque de participation.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('1c3b9eb2-3e17-4722-a2ee-0b94061906e1', 'fr', 'Tu ressens une anxiété intense avant d’aborder. Qu’est-ce que tu dois faire passer en premier ?', '["Étudier plus de techniques pour peaufiner ta phrase d’accroche", "Te préparer mentalement pendant des heures", "Attendre que l’anxiété baisse", "Faire un petit échange aujourd’hui, quel que soit le résultat"]'::jsonb, 'Une exposition répétée, en multipliant les approches, habitue ton système nerveux à se sentir en sécurité.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('1e482ecd-547c-44e9-96d0-74c25f5ef813', 'fr', 'Les femmes aiment discuter avec toi, mais ne flirtent jamais en retour. Quel est ton point de blocage ?', '["Être sympathique et agréable", "Introduire de la tension séductrice ou du jeu", "Faire accepter tes premières approches", "Donner suite après avoir obtenu un numéro"]'::jsonb, 'Les résultats changent quand ta pratique se concentre sur le maillon le plus faible de l’échange.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('28e3345b-49dd-42c7-86fd-931c5c032deb', 'fr', 'Tu es naturellement calme et réfléchi. Quel style de flirt te va le mieux ?', '["Des pauses, un regard direct et des questions inattendues", "Des affirmations audacieuses, fortes et pleines d’énergie", "Copier les blagues d’un coach drôle", "Te forcer à faire des compliments directs"]'::jsonb, 'Applique les principes à travers ta personnalité naturelle pour un lien authentique.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('324d0f15-f4f3-4d1e-aa8a-9a3dbbda9f55', 'fr', 'Comment le fait de rejoindre des activités de groupe change-t-il tes chances de faire des rencontres ?', '["Ça garantit des liens immédiats", "Ça crée une exposition régulière et des passerelles possibles vers de nouvelles personnes", "Ça garde ton monde petit et prévisible"]'::jsonb, 'Les groupes multiplient les rencontres et les liens indirects, ce qui crée des occasions naturelles.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('360f9f51-86bf-4779-ab39-a8155afc9bdd', 'fr', 'Pourquoi partager de façon sélective crée-t-il plus d’attirance que tout dévoiler ?', '["Ça la noie sous les informations à traiter", "Ça laisse des zones d’incertitude qui nourrissent la curiosité", "Ça invite son imagination à combler les vides"]'::jsonb, 'Le mystère pousse à s’interroger, ce qui rend la découverte progressive et captivante.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('4826161e-e13f-4b37-8fe4-6ee85878fd7e', 'fr', 'Quel changement d’état d’esprit faut-il pour créer plus d’occasions ?', '["Intégrer volontairement l’exposition sociale à ton quotidien", "Dire oui à de nouvelles activités même quand tu n’es pas sûr", "T’attendre à ce que chaque effort donne tout de suite des résultats"]'::jsonb, 'Une action régulière élargit ton monde, ce qui laisse les occasions apparaître.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('48fe4298-aeef-4a2e-85e5-f1d2e2592692', 'fr', 'Que permet l’esprit d’expérimentation ?', '["Échouer sans te sentir un raté", "Apprendre de tes expériences au lieu de les juger", "Te constituer une base de ce qui marche selon les contextes", "Toutes les réponses ci-dessus"]'::jsonb, 'Quand tu vois tes approches comme des expériences, un refus devient une donnée, pas un échec.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('51e669d2-f554-48ce-843b-4c367370982e', 'fr', 'Pourquoi multiplier les approches réduit-il l’anxiété d’aborder ?', '["Ça donne de meilleures phrases d’accroche", "Ça entraîne le système nerveux par l’habitude", "Ça réduit la menace perçue avec le temps", "Ça remplace la peur par l’assurance grâce à la logique"]'::jsonb, 'L’anxiété diminue grâce à une exposition répétée et sans danger, pas grâce à la réflexion ou à la préparation.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('5eb79a5b-9ac8-45c2-9e9d-423d1d2916e4', 'fr', 'Ta phrase d’accroche reçoit une réponse polie, mais plate. Que dois-tu te dire ensuite ?', '["« Cette accroche n’a pas pris. Qu’est-ce que je pourrais ajuster la prochaine fois ? »", "« J’ai échoué, je suis nul pour ça. »", "« De toute façon, elle n’était pas intéressée. »", "« Je devrais arrêter d’aborder pour aujourd’hui. »"]'::jsonb, 'Analyse les paramètres pour recueillir des informations utiles pour tes prochains essais.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('5feee0d2-d777-41cf-a17b-4a10cdba7c30', 'fr', 'Pourquoi avoir une vie intéressante aide-t-il l’attirance ?', '["Ton propre pouvoir d’attraction : les gens viennent naturellement vers toi", "Des sujets de conversation qui viennent naturellement", "Les deux réponses ci-dessus"]'::jsonb, 'Une vie intéressante produit de vraies expériences qui attirent naturellement les gens.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('609555df-ed41-4234-bb64-85b739483e7a', 'fr', 'Quelles activités créent une exposition régulière à de nouvelles personnes ?', '["Des cours collectifs de sport à horaires fixes", "Travailler dans des cafés plutôt que chez toi", "Des clubs qui se retrouvent régulièrement : course à pied, cuisine, etc.", "Toutes les réponses ci-dessus"]'::jsonb, 'Multiplier les rencontres en t’exposant volontairement laisse les possibilités apparaître.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('63f71c1b-3eab-460c-91fa-a52c22044efb', 'fr', 'Qu’est-ce qui montre qu’un homme a une vie en dehors du travail ?', '["Il parle de ce qu’il apprend ou de ses projets en cours", "Il parle du monde avec curiosité", "Il évite de parler de lui", "Il a des histoires tirées d’une vie bien remplie"]'::jsonb, 'Les expériences vécues se voient naturellement dans la façon de parler.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('6cbe70b0-30ea-4012-9096-6f2a5efad2ed', 'fr', 'Pourquoi le statut social est-il un signal d’attirance si puissant au départ ?', '["Il montre directement la richesse ou la célébrité", "Les réactions positives des autres montrent que tu es agréable", "On fait confiance à l’avis du groupe sur qui est désirable"]'::jsonb, 'Le statut reflète la valeur que l’environnement t’accorde, ce qui influence la réceptivité.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('79d8a1ab-f362-4b54-96da-46e704c946f6', 'fr', 'Quels signaux font baisser ton statut social perçu dans un lieu ?', '["Rôder en bordure de la salle", "Être accueilli chaleureusement par plusieurs personnes", "Des approches forcées ou brusques", "Être visiblement à l’aise dans l’espace"]'::jsonb, 'Un placement maladroit et des échanges forcés montrent que tu es mal intégré dans le lieu.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('835a240c-8530-4ebc-a1a2-6750a3953290', 'fr', 'Tu sais faire en sorte que les gens se sentent écoutés. Sur quoi pourrais-tu miser ?', '["Une répartie très énergique", "Raconter des histoires bruyamment", "Des compliments directs et audacieux", "Des questions profondes et une écoute active"]'::jsonb, 'Utilise ta force naturelle pour créer une complicité authentique.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('929ddae6-c1d3-4185-b3f1-b34b2eb34346', 'fr', 'Tu es naturellement intense et direct. Quel style de flirt te va le mieux ?', '["Une répartie légère et des blagues idiotes", "Un regard soutenu, avec des mots pesés et des pauses", "De longues histoires et des allusions indirectes", "Être d’accord sur tout, avec trop de politesse"]'::jsonb, 'Applique les principes à travers ta personnalité naturelle pour un lien authentique.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('95566af1-be99-4506-bdd8-59bc1224aa22', 'fr', 'De quoi la régularité te protège-t-elle avant tout ?', '["Du manque de motivation", "Des plateaux de progression", "Du retour de l’anxiété et de l’installation de l’évitement", "Du rejet social"]'::jsonb, 'Une pratique régulière protège tes acquis et évite que tes compétences s’émoussent. Reste régulier.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('971392d7-a116-4cf8-b454-2526464b795a', 'fr', 'Pourquoi multiplier les approches réduit-il l’anxiété avec le temps ?', '["Le système nerveux s’adapte à ce qui lui est familier", "Ça apprend au corps, par l’habitude, qu’il est en sécurité", "Une exposition répétée réduit la réaction de menace", "Toutes les réponses ci-dessus"]'::jsonb, 'Des répétitions régulières désensibilisent la peur par l’expérience.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('98fd5abd-0203-4c21-bbff-f869372f2335', 'fr', 'Qu’est-ce qui montre un statut social élevé dans un environnement ?', '["Les gens viennent vers toi et t’incluent dans les conversations", "Les autres te parlent avec chaleur et plaisir", "Tu te déplaces dans l’espace avec aisance, sans maladresse", "Toutes les réponses ci-dessus"]'::jsonb, 'Un statut élevé se voit à ton aisance, au fait d’être inclus et à la façon dont les autres réagissent naturellement à toi.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('99d720d0-bfa1-45ff-a43b-49f9f15f631e', 'fr', 'Pourquoi la régularité rend-elle l’approche plus facile avec le temps ?', '["Les connexions neuronales deviennent plus efficaces", "Le cerveau range ce comportement dans la catégorie « normal »", "La peur est éliminée par la logique"]'::jsonb, 'La répétition renforce les connexions neuronales et fait évoluer ton identité, ce qui réduit l’effort.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('afbf1b2d-da55-4722-9e2b-7044a65e1227', 'fr', 'Tu n’abordes que le week-end, dans des contextes très stressants. Quel risque cours-tu ?', '["T’habituer plus vite grâce à l’intensité", "Réduire tout de suite ton anxiété", "Développer vite de solides compétences", "Progresser lentement, faute d’exposition fréquente"]'::jsonb, 'Des répétitions rares gardent la situation peu familière, ce qui prolonge une anxiété forte.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('b1dad7ff-1e71-4b22-b734-b1ca8f1c8973', 'fr', 'Quels signes montrent qu’un entourage freine ta progression ?', '["Se moquer de tes efforts pour rencontrer de nouvelles personnes", "Éviter systématiquement les lieux où l’on rencontre du monde", "Encourager le confort plutôt que l’action", "Soutenir les petits risques que tu prends"]'::jsonb, 'Un entourage qui banalise l’évitement fait discrètement fondre ton assurance.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('b72f662b-1295-4658-bb7a-cf26f14aea82', 'fr', 'Comment te construire un statut ?', '["Échanger naturellement avec les gens présents", "Te déplacer dans l’espace avec aisance", "Rejoindre des conversations et y apporter quelque chose", "T’isoler pour paraître mystérieux"]'::jsonb, 'Un vrai engagement social prouve que les autres apprécient ta présence.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('bfac329b-b9e4-4dbf-9045-786f91c69c40', 'fr', 'Tu es naturellement chaleureux et empathique. Quel style de flirt te va le mieux ?', '["Des questions profondes et curieuses qui montrent un vrai intérêt", "Des affirmations agressives et audacieuses", "Une énergie bruyante et des taquineries en rafale", "Éviter tout sujet personnel"]'::jsonb, 'Applique les principes à travers ta personnalité naturelle pour un lien authentique.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('c3ffa6e0-05e2-488d-a7f5-392b781d19f9', 'fr', 'Tu préfères rester chez toi parce que c’est plus facile. Quel est le coût caché ?', '["Moins d’occasions de faire des rencontres", "Une productivité réduite", "De l’énergie perdue", "Des exigences plus basses"]'::jsonb, 'Le confort échange une facilité à court terme contre l’isolement à long terme.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('d089015f-4147-45d7-a8b2-91b48d80f944', 'fr', 'Pourquoi étudier des techniques précises ne règle-t-il pas l’anxiété d’aborder ?', '["Les techniques ne marchent pas", "L’anxiété est irrationnelle", "Les connaissances sont inaccessibles quand le système nerveux est en mode menace", "L’assurance ne s’apprend pas"]'::jsonb, 'L’anxiété diminue grâce à une exposition répétée et sans danger, pas grâce à la réflexion ou à la préparation.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('d5674fd6-bd0f-4780-bb0b-5afca3a759d9', 'fr', 'Quel est le but principal quand tu crées plus d’occasions de rencontres ?', '["Faire en sorte que chaque sortie débouche sur un rendez-vous", "T’exposer régulièrement à de nouvelles personnes", "Multiplier les rencontres pour que les occasions viennent naturellement"]'::jsonb, 'Multiplier les rencontres en t’exposant volontairement laisse les possibilités apparaître.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('d8b68638-1540-4aa1-a96a-3d316ea102b3', 'fr', 'Comment ton entourage t’aide-t-il à aborder et à faire des rencontres ?', '["Tes amis peuvent t’encourager à agir", "Ton environnement peut rendre le courage plus facile", "Tes amis peuvent te donner des occasions de rencontrer de nouvelles personnes", "Toutes les réponses ci-dessus"]'::jsonb, 'Ton environnement encourage ta progression ou renforce ton hésitation.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('db1590aa-6103-4532-bff1-7bcf8930cfef', 'fr', 'Quels comportements préservent le mystère dans une conversation ?', '["Répondre aux questions sans trop t’expliquer", "Tout partager tôt pour être transparent", "Dévoiler ta profondeur progressivement", "Laisser de la place pour des questions de relance"]'::jsonb, 'Le mystère, c’est une question de rythme, pas de rétention ou d’esquive.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('db1e61cd-85f6-4787-a686-1e10e72ffe10', 'fr', 'Quels éléments de ton mode de vie rendent naturellement les conversations plus faciles et plus prenantes ?', '["Des loisirs ou des compétences que tu entretiens", "La curiosité pour de nouvelles expériences", "Attendre la bonne personne pour mettre du piment dans ta vie", "Des projets sur lesquels tu travailles activement"]'::jsonb, 'Une vie intéressante fournit sans effort de quoi alimenter la conversation.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('dda0749c-c9ba-4e4a-affe-2eb786b6ec12', 'fr', 'Pourquoi une vie intéressante attire-t-elle au-delà du charme superficiel ?', '["Elle fournit de vraies histoires et de la matière pour la conversation", "Elle montre que tu as un monde à toi, indépendant de tes relations", "Elle repose uniquement sur des réussites impressionnantes"]'::jsonb, 'Une vie intéressante produit de vraies expériences qui attirent naturellement les gens.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('e2c71b43-3067-41f1-9745-de39c9164feb', 'fr', 'Tu es naturellement drôle. Quel style de flirt te va le mieux ?', '["Miser sur l’humour et la taquinerie", "Utiliser un regard intense et des pauses", "Faire des affirmations directes et audacieuses", "Rester complètement sérieux"]'::jsonb, 'Appuie-toi sur ton humour pour créer de la tension à ta façon.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('e310c934-f43c-49b6-b568-70a8a9baf70c', 'fr', 'Quels résultats comptent quand même comme un progrès avec l’esprit d’expérimentation ?', '["Un refus clair", "Une réaction neutre", "Une conversation courte", "Toutes les réponses ci-dessus"]'::jsonb, 'Tant que tu en tires une leçon, la rencontre est une réussite.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('e3d69b71-e0dd-4f11-b25f-ecc126cd2696', 'fr', 'Une approche se termine vite, avec peu d’implication. Sur quoi te concentrer ensuite ?', '["Le fait que ça prouve que tu n’es pas à la hauteur", "Éviter les situations semblables", "Les paramètres que tu peux tester autrement : moment, énergie, phrase d’accroche", "Le besoin de réussir tout de suite la prochaine fois"]'::jsonb, 'Analyse les paramètres pour recueillir des informations utiles pour tes prochains essais.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('f3ef742e-f78a-42cd-a813-76571d61bce5', 'fr', 'Pourquoi le mystère augmente-t-il l’attirance ?', '["Il te fait paraître indisponible", "Il donne à son imagination de quoi travailler", "Il cache ton insécurité", "Il empêche le lien émotionnel"]'::jsonb, 'La curiosité naît d’informations incomplètes. Le mystère la garde mentalement impliquée.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
commit;
